draw:
var th = p.angle * Math.PI / 180;
var px = W * 0.46, py = H * 0.12;
var len = H * 0.52;
var bx = px + len * Math.sin(th), by = py + len * Math.cos(th);
var F = "12px ui-sans-serif, system-ui, sans-serif";

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 8 * Math.cos(a - 0.4), y1 - 8 * Math.sin(a - 0.4));
  ctx.lineTo(x1 - 8 * Math.cos(a + 0.4), y1 - 8 * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

// ceiling
ctx.fillStyle = C.faint;
ctx.fillRect(px - W * 0.22, py - 8, W * 0.44, 8);

// vertical reference
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, py + len + 30); ctx.stroke();
ctx.setLineDash([]);

// angle arc
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(px, py, 40, Math.PI / 2 - th, Math.PI / 2); ctx.stroke();
ctx.fillStyle = C.ink; ctx.font = F;
ctx.fillText("theta = " + p.angle.toFixed(0) + " deg", px + 8, py + 56);

// string
ctx.strokeStyle = C.ink; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(bx, by); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("L", (px + bx) / 2 - 14, (py + by) / 2);

// unit vectors along and across the string
var ux = Math.sin(th), uy = Math.cos(th);      // away from pivot
var tx = Math.cos(th), ty = -Math.sin(th);     // tangential, toward the bottom

var g = H * 0.30;   // pixel length standing for mg

// weight mg, straight down
arrow(bx, by, bx, by + g, C.figure);
ctx.fillStyle = C.figure;
ctx.fillText("mg", bx + 6, by + g - 4);

// component along the string: mg cos(theta)
arrow(bx, by, bx + ux * g * Math.cos(th), by + uy * g * Math.cos(th), C.faint);
ctx.fillStyle = C.ink;
ctx.fillText("mg cos theta", bx + ux * g * Math.cos(th) + 6, by + uy * g * Math.cos(th) + 4);

// tangential component: mg sin(theta), the restoring force
arrow(bx, by, bx - tx * g * Math.sin(th), by - ty * g * Math.sin(th), C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("mg sin theta", bx - tx * g * Math.sin(th) - 92, by - ty * g * Math.sin(th) - 8);

// tension
arrow(bx, by, bx - ux * g * Math.cos(th), by - uy * g * Math.cos(th), C.rule);
ctx.fillStyle = C.ink;
ctx.fillText("tension", bx - ux * g * Math.cos(th) * 0.6 - 58, by - uy * g * Math.cos(th) * 0.6);

// bob
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(bx, by, 9, 0, 2 * Math.PI); ctx.fill();

// sine versus angle, small inset graph
var gx0 = W * 0.06, gy0 = H * 0.94, gw = W * 0.26, gh = H * 0.34;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(gx0, gy0 - gh); ctx.lineTo(gx0, gy0); ctx.lineTo(gx0 + gw, gy0); ctx.stroke();
var maxA = Math.PI / 3;
ctx.strokeStyle = C.rule;
ctx.beginPath();
for (var i = 0; i <= 40; i++) {
  var a1 = maxA * i / 40;
  var X = gx0 + gw * a1 / maxA, Y = gy0 - gh * a1 / maxA;
  i === 0 ? ctx.moveTo(X, Y) : ctx.lineTo(X, Y);
}
ctx.stroke();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
for (var j = 0; j <= 40; j++) {
  var a2 = maxA * j / 40;
  var X2 = gx0 + gw * a2 / maxA, Y2 = gy0 - gh * Math.sin(a2) / maxA;
  j === 0 ? ctx.moveTo(X2, Y2) : ctx.lineTo(X2, Y2);
}
ctx.stroke();
ctx.fillStyle = C.ink; ctx.font = F;
ctx.fillText("theta", gx0 + gw * 0.42, gy0 - gh * 0.86);
ctx.fillStyle = C.accent;
ctx.fillText("sin theta", gx0 + gw * 0.30, gy0 - gh * 0.30);
// marker at the current angle
var frac = Math.min(th / maxA, 1);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(gx0 + gw * frac, gy0 - gh * Math.sin(th) / maxA, 4, 0, 2 * Math.PI); ctx.fill();

var err = (th === 0) ? 0 : (th - Math.sin(th)) / th * 100;
out.note = "theta = " + th.toFixed(3) + " rad, sin theta = " + Math.sin(th).toFixed(3) +
  " - restoring force is " + err.toFixed(2) + "% weaker than the straight-line law";

var L = p.length, g = p.gravity, th0 = p.amp * Math.PI / 180;
var T0 = 2 * Math.PI * Math.sqrt(L / g);
var Tex = T0 * (1 + th0 * th0 / 16 + 11 * Math.pow(th0, 4) / 3072);
var th = th0 * Math.cos(2 * Math.PI * t / Tex);
var F = "12px ui-sans-serif, system-ui, sans-serif";

var px = W * 0.5, py = H * 0.10;
var scale = (H * 0.66) / 2.5;          // pixels per metre, longest string fits
var len = L * scale;
var bx = px + len * Math.sin(th), by = py + len * Math.cos(th);

// ceiling
ctx.fillStyle = C.faint;
ctx.fillRect(px - W * 0.3, py - 8, W * 0.6, 8);

// vertical reference
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, py + len + 24); ctx.stroke();
ctx.setLineDash([]);

// swept arc between the turning points
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(px, py, len, Math.PI / 2 - th0, Math.PI / 2 + th0); ctx.stroke();

// turning point markers
ctx.fillStyle = C.faint;
ctx.beginPath(); ctx.arc(px + len * Math.sin(th0), py + len * Math.cos(th0), 4, 0, 2 * Math.PI); ctx.fill();
ctx.beginPath(); ctx.arc(px - len * Math.sin(th0), py + len * Math.cos(th0), 4, 0, 2 * Math.PI); ctx.fill();

// string and bob
ctx.strokeStyle = C.ink; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(bx, by); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(bx, by, 10, 0, 2 * Math.PI); ctx.fill();

ctx.fillStyle = C.ink; ctx.font = F;
ctx.fillText("L = " + L.toFixed(2) + " m", px + 10, py + len * 0.5);
ctx.fillText("amplitude " + p.amp.toFixed(0) + " deg", px - W * 0.28, py + 24);

// angle against time, drawn along the bottom
var gy = H * 0.90, x0 = W * 0.06, x1 = W * 0.94;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, gy); ctx.lineTo(x1, gy); ctx.stroke();
var span = 4 * Tex;                    // seconds across the plot
ctx.strokeStyle = C.accent; ctx.lineWidth = 1.5;
ctx.beginPath();
for (var i = 0; i <= 200; i++) {
  var tt = t - span * (200 - i) / 200;
  var X = x0 + (x1 - x0) * i / 200;
  var Y = gy - (H * 0.07) * Math.cos(2 * Math.PI * tt / Tex);
  i === 0 ? ctx.moveTo(X, Y) : ctx.lineTo(X, Y);
}
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("angle against time", x0, gy + 18);

out.note = "small-angle T = " + T0.toFixed(3) + " s, true T = " + Tex.toFixed(3) +
  " s, slow by " + ((Tex / T0 - 1) * 100).toFixed(2) + "%";

var L = 1.0, d = p.d, g = 9.8;
var Ioverm = L * L / 12 + d * d;
var Leq = Ioverm / d;
var T = 2 * Math.PI * Math.sqrt(Leq / g);
var th0 = 0.22;
var th = th0 * Math.cos(2 * Math.PI * t / T);
var F = "12px ui-sans-serif, system-ui, sans-serif";

var px = W * 0.5, py = H * 0.14;
var scale = H * 0.60;                 // pixels per metre of rod
var ux = Math.sin(th), uy = Math.cos(th);   // down the rod
var topX = px - ux * (L / 2 - d) * scale, topY = py - uy * (L / 2 - d) * scale;
var botX = px + ux * (L / 2 + d) * scale, botY = py + uy * (L / 2 + d) * scale;

// support bracket
ctx.fillStyle = C.faint;
ctx.fillRect(px - W * 0.14, py - 26, W * 0.28, 7);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(px, py - 19); ctx.lineTo(px, py); ctx.stroke();

// vertical reference through the pivot
ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, py + scale * 0.8); ctx.stroke();
ctx.setLineDash([]);

// the rod
ctx.strokeStyle = C.figure; ctx.lineWidth = 7; ctx.lineCap = "round";
ctx.beginPath(); ctx.moveTo(topX, topY); ctx.lineTo(botX, botY); ctx.stroke();
ctx.lineWidth = 1; ctx.lineCap = "butt";

// pivot
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px, py, 5, 0, 2 * Math.PI); ctx.fill();

// centre of mass, filled
var cmX = px + ux * d * scale, cmY = py + uy * d * scale;
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cmX, cmY, 5, 0, 2 * Math.PI); ctx.fill();

// centre of oscillation, hollow
var coX = px + ux * Leq * scale, coY = py + uy * Leq * scale;
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(coX, coY, 6, 0, 2 * Math.PI); ctx.stroke();

// the equivalent simple pendulum, drawn faintly alongside
var sx = px + W * 0.30;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(sx, py); ctx.lineTo(sx + ux * Leq * scale, py + uy * Leq * scale); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.beginPath(); ctx.arc(sx + ux * Leq * scale, py + uy * Leq * scale, 8, 0, 2 * Math.PI); ctx.fill();
ctx.fillStyle = C.ink; ctx.font = F;
ctx.fillText("equivalent simple pendulum", sx - W * 0.10, py - 34);

ctx.fillStyle = C.accent;
ctx.fillText("centre of mass", cmX + 10, cmY - 4);
ctx.fillText("centre of oscillation", coX + 10, coY + 14);
ctx.fillStyle = C.ink;
ctx.fillText("pivot", px + 10, py - 6);

out.note = "d = " + d.toFixed(3) + " m, equivalent length = " + Leq.toFixed(3) +
  " m, T = " + T.toFixed(3) + " s";
